const cuiPath = resolve(get('--cui', join(root, 'bw-circuit-ui-pinned')));
const supplierPath = resolve(get('--supplier', join(root, 'sb3-creator')));
const scenario = get('--case', 'big');
assert(['big', 'steady', 'reversed'].includes(scenario));
const warmupMs = Number(get('--warmup-ms', scenario === 'steady' ? 22 : scenario === 'reversed' ? 5 : 6));
const endMs = Number(get('--end-ms', warmupMs + 3));
const dtMs = Number(get('--dt-ms', 0.02));
const maxK = get('--max-rf-k', null) === null ? null : Number(get('--max-rf-k', null));
const explicitOnly = process.argv.includes('--explicit-only');
const globalMode = process.argv.includes('--global-mode');
const outputPath = resolve(get('--out', join(import.meta.dirname, 'squegg-probe.json')));
assert(Number.isFinite(warmupMs) && Number.isFinite(endMs) && endMs > warmupMs && warmupMs >= 0);
assert(Number.isFinite(dtMs) && dtMs > 0);
assert(maxK === null || (Number.isInteger(maxK) && maxK >= 0 && maxK <= 15));

const { RadioFrontEnd } = await import(pathToFileURL(join(boardPath, 'src/radio.js')));
const { BandIntegrator } = await import(pathToFileURL(join(boardPath, 'src/rf-bands.js')));
if (explicitOnly) BandIntegrator.prototype.implicit = false;
if (maxK !== null || globalMode) {
    const refresh = RadioFrontEnd.prototype.refresh;
    const configured = new WeakSet();
    RadioFrontEnd.prototype.refresh = function (...args) {
        const result = refresh.apply(this, args);
        for (const band of this._bands) if (!configured.has(band)) {
            if (maxK !== null) {
                const previous = band._kForRotation;
                band._kForRotation = function () { return Math.min(maxK, previous ? previous.call(this) : maxK); };
            }
            if (globalMode) {
                band.integ.blocks = [band.integ.ports.map((_, q) => q)];
                band.integ._lus.clear();
            }
            configured.add(band);
        }
        return result;
    };
}
const { injectEngine } = await import(pathToFileURL(join(supplierPath, 'scripts/lib/engine-surface.mjs')));
const { BENCHES, benchIds } = await import(pathToFileURL(join(supplierPath, 'scripts/lib/lab-benches-r7b.mjs')));
const circuitPath = join(supplierPath, 'examples/lab-meissner-squegg/circuit.json');
const git = path => execFileSync('git', ['rev-parse', 'HEAD'], { cwd: path, encoding: 'utf8' }).trim();
const hash = path => createHash('sha256').update(readFileSync(path)).digest('hex');
const metadata = {
    board: git(boardPath), cui: git(cuiPath), supplier: git(supplierPath), scenario,
    warmupMs, endMs, dtMs, runtimeDiagnostic: { explicitOnly, maxK, globalMode },
    sourceSha256: Object.fromEntries(['src/radio.js', 'src/rf-bands.js'].map(file => [file, hash(join(boardPath, file))])),
    circuitSha256: hash(circuitPath),
};
console.log(JSON.stringify({ started: metadata }));
const { Circuit } = await injectEngine({ board: boardPath, cui: cuiPath });
const circuit = Circuit.fromJSON(JSON.parse(readFileSync(circuitPath, 'utf8')));
const board = circuit.board, ids = benchIds(BENCHES['lab-meissner-squegg']);
if (scenario === 'big') board.setControl(ids.sbig, 0);
if (scenario === 'reversed') { board.setControl(ids.sa, 1); board.setControl(ids.sb, 1); }
const net = (name, terminal) => {
    const found = board.getNets().find(n => n.terminals.some(t => t.part === ids[name] && t.terminal === terminal));
    assert(found, `${name}.${terminal}`);
    return found.id;
};
const observed = Object.fromEntries(Object.entries({
    tank: ['tct', 'b'], base: ['q', 'base'], emitter: ['q', 'emitter'],
    detector: ['d', 'cathode'], reservoir: ['cb', 'a'], bigBypass: ['cbig', 'a'],
}).map(([key, [name, terminal]]) => [key, net(name, terminal)]));
let timeMs = 0;
const run = ms => {
    timeMs += ms;
    board.advanceTo(BigInt(Math.round(timeMs * 1e6)));
    assert.equal(board.transientAnalysisStatus().failure, null, `transient failure at ${timeMs} ms`);
    assert.equal(board._radio?.error ?? null, null, `RF failure at ${timeMs} ms`);
};
const rows = [];
let failure = null;
try {
    run(warmupMs);
    for (let i = 0; i < Math.round((endMs - warmupMs) / dtMs); i++) {
        run(dtMs);
        rows.push({ timeMs,
            rf: Math.max(0, ...(board._radio?.bandAmplitudes(observed.tank) ?? []).map(x => x.volts)),
            ...Object.fromEntries(Object.entries(observed).map(([key, id]) => [key, board.nodeVoltages.get(id) ?? 0])),
            bands: board._radio._bands.map(band => ({
                centreHz: band.hz, k: band.k, growth: band.growth, oscHz: band.oscHz,
                rotationHz: band.rotationHz(), blocks: band.integ.blocks,
                ports: band.integ.portVoltages(), implicitSteps: band.integ.implicitSteps ?? 0,
            })),
        });
        if ((i + 1) % 150 === 0) console.log(JSON.stringify({ progressMs: timeMs }));
    }
} catch (error) {
    failure = { message: error.message, transient: board.transientAnalysisStatus().failure, radio: board._radio?.error ?? null };
    process.exitCode = 1;
}
const range = key => ({ min: Math.min(...rows.map(x => x[key])), max: Math.max(...rows.map(x => x[key])) });
const summary = rows.length ? { rf: range('rf'), emitter: range('emitter'), reservoir: range('reservoir'),
    detector: range('detector'), bigBypass: range('bigBypass'), tone: board.buzzerTone(ids.ep),
    junctions: board._radio._sys.junctions.map(j => ({ kind: j.kind, p: j.p, partId: j.d.partId })),
} : null;
writeFileSync(outputPath, JSON.stringify({ metadata, failure, summary, rows }) + '\n');
console.log(JSON.stringify({ outputPath, failure, summary }));

