import { writeFileSync } from 'node:fs';
import { BandIntegrator } from '../bw-board/src/rf-bands.js';

const original = BandIntegrator.prototype.step;
const evidence = { note: 'Read-only per-step shadow: same source and exact noisy RHS, legacy all-port mode versus production device blocks.', compared: 0, selected: [] };
const norm = p => Math.sqrt(p.reduce((s, [r, i]) => s + r * r + i * i, 0));
const amps = p => p.map(x => Math.hypot(...x));
const copy = x => ({ re: Float64Array.from(x.re), im: Float64Array.from(x.im) });
BandIntegrator.prototype.step = function(k, stamps, source, noise, previous = null) {
    if (this.t > 0.002 || this.blocks.length < 2) return original.call(this, k, stamps, source, noise, previous);
    const start = this.portVoltages();
    const events = [];
    let sourceValue, noiseBefore, noiseAfter;
    const output = original.call(this, k, ports => {
        const S = stamps(ports);
        events.push({ ports: ports.map(p => p.slice()), S: Object.fromEntries(Object.entries(S).map(([key, value]) => [key, Array.from(value)])) });
        return S;
    }, t => (sourceValue = copy(source(t))), noise ? (rr, ri, h) => {
        noiseBefore = { re: Float64Array.from(rr), im: Float64Array.from(ri) };
        noise(rr, ri, h);
        noiseAfter = { re: Float64Array.from(rr), im: Float64Array.from(ri) };
    } : null, previous);
    if (events.length <= 1) return output;
    const shadow = new BandIntegrator({ N: this.N, ports: this.ports, inj: this.inj });
    shadow.setLinear(this._lin.Y0, this._lin.Y1);
    shadow.X = copy(this.X); shadow.t = this.t;
