        const S = stamps(ports);
        legacyEvents.push({ ports: ports.map(p => p.slice()), S: Object.fromEntries(Object.entries(S).map(([key, value]) => [key, Array.from(value)])) });
        return S;
    }, () => copy(sourceValue), noise ? (rr, ri) => {
        if (!rr.every((v,i) => v === noiseBefore.re[i]) || !ri.every((v,i) => v === noiseBefore.im[i])) throw new Error('shadow noisy RHS differs before noise');
        rr.set(noiseAfter.re); ri.set(noiseAfter.im);
    } : null, previous);
