        legacy: { ports: legacyPorts, amps: amps(legacyPorts), inconsistent: legacy.inconsistent, calls: legacyEvents.length, events: legacyEvents },
        largestDifference, totalNormDifference: norm(actualPorts) - norm(legacyPorts),
