// Two independent passive nonlinear RC channels, independently forced by
// DC currents. One amplitude decays while the other grows. The end state
// at k=14 is manufactured directly from each channel's backward-Euler KCL.
const C = 1e-9;
const g = x => 1e-7 * Math.exp(x / VT);
const initial = [0.2, 0.05], desired = [0.19, 0.09];
